namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeCategory
{
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string Icon { get; set; } = string.Empty;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly List<RecipeCategory> _categories;

    public RecipeService()
    {
        _categories =
        [
            new() { Name = "Breakfast", Description = "Start your day right", Icon = "🥞" },
            new() { Name = "Lunch", Description = "Midday meals and light bites", Icon = "🥗" },
            new() { Name = "Dinner", Description = "Hearty evening dishes", Icon = "🍝" },
            new() { Name = "Desserts", Description = "Sweet treats and baked goods", Icon = "🍰" },
            new() { Name = "Snacks", Description = "Quick bites between meals", Icon = "🍿" },
        ];

        _recipes =
        [
            new()
            {
                Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
                Ingredients = "2 cups flour\n2 eggs\n1 cup milk\n2 tbsp sugar\n1 tsp baking powder\nButter for cooking",
                Steps = "1. Mix dry ingredients\n2. Whisk eggs and milk together\n3. Combine wet and dry ingredients\n4. Cook on buttered griddle until bubbles form\n5. Flip and cook until golden",
                AverageRating = 4.5, RatingCount = 12
            },
            new()
            {
                Id = 2, Title = "Avocado Toast", Category = "Breakfast",
                Ingredients = "2 slices sourdough bread\n1 ripe avocado\nSalt and pepper\nRed pepper flakes\nLemon juice",
                Steps = "1. Toast bread until golden\n2. Mash avocado with lemon juice, salt, and pepper\n3. Spread on toast\n4. Top with red pepper flakes",
                AverageRating = 4.2, RatingCount = 8
            },
            new()
            {
                Id = 3, Title = "Caesar Salad", Category = "Lunch",
                Ingredients = "1 head romaine lettuce\n1/2 cup croutons\n1/4 cup parmesan\nCaesar dressing\nGrilled chicken (optional)",
                Steps = "1. Wash and chop lettuce\n2. Toss with dressing\n3. Add croutons and parmesan\n4. Top with grilled chicken if desired",
                AverageRating = 4.0, RatingCount = 6
            },
            new()
            {
                Id = 4, Title = "Spaghetti Carbonara", Category = "Dinner",
                Ingredients = "400g spaghetti\n200g pancetta\n4 egg yolks\n1 cup pecorino romano\nBlack pepper",
                Steps = "1. Cook pasta in salted water\n2. Fry pancetta until crispy\n3. Mix egg yolks with cheese and pepper\n4. Toss hot pasta with pancetta\n5. Remove from heat, stir in egg mixture\n6. Serve immediately with extra cheese",
                AverageRating = 4.8, RatingCount = 20
            },
            new()
            {
                Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts",
                Ingredients = "200g dark chocolate\n100g butter\n2 eggs\n2 egg yolks\n1/4 cup sugar\n2 tbsp flour",
                Steps = "1. Melt chocolate and butter together\n2. Whisk eggs, yolks, and sugar until thick\n3. Fold in chocolate mixture and flour\n4. Pour into greased ramekins\n5. Bake at 220°C for 12 minutes\n6. Invert onto plates and serve immediately",
                AverageRating = 4.9, RatingCount = 15
            },
            new()
            {
                Id = 6, Title = "Trail Mix Energy Bites", Category = "Snacks",
                Ingredients = "1 cup oats\n1/2 cup peanut butter\n1/3 cup honey\n1/2 cup chocolate chips\n1/4 cup dried cranberries",
                Steps = "1. Mix all ingredients in a bowl\n2. Refrigerate for 30 minutes\n3. Roll into bite-sized balls\n4. Store in refrigerator",
                AverageRating = 4.3, RatingCount = 9
            },
        ];
    }

    public List<RecipeCategory> GetCategories() => _categories;

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Count > 0 ? _recipes.Max(r => r.Id) + 1 : 1;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetRecipeById(recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount;
        recipe.RatingCount++;
        recipe.AverageRating = (totalStars + stars) / recipe.RatingCount;
    }
}

